/**
 * Deportes alternativos para Educación Física (petición del dueño,
 * 23-10-2026, a partir de su guía de iniciación y de oposdeport y edufisrd):
 * una progresión en 3 sesiones por deporte, con actividades transversales
 * (compartidas) y específicas (propias de cada deporte).
 *
 * En el banco (`lib/bancoEF.ts`) cada deporte es una ficha breve; al abrirla,
 * `EfActividades` muestra aquí su progresión completa. Los códigos de las
 * actividades (T1, K1, C1…) son los de la guía del dueño.
 */
import type { ModalidadEF } from '../types/ef';

type Lang = 'es' | 'ca' | 'en';
/** Castellano, catalán e inglés. */
type T3 = readonly [es: string, ca: string, en: string];

export interface ActividadGuia {
  codigo: string;
  titulo: T3;
  objetivo: T3;
  desarrollo: T3;
}

export interface SesionGuia {
  titulo: T3;
  /** Códigos de las actividades de la sesión, en orden (transversales y específicas). */
  actividades: string[];
}

export interface DeporteAlternativo {
  /** Coincide con el id del banco sin el prefijo `banco-` (korfball, colpbol…). */
  id: string;
  nombre: T3;
  modalidad: ModalidadEF;
  /** Breve explicación del deporte, la que se ve en su ficha. */
  rasgos: T3;
  sesiones: SesionGuia[];
  especificas: ActividadGuia[];
}

