const IDX: Record<Lang, 0 | 1 | 2> = { es: 0, ca: 1, en: 2 };

/** La guía de un deporte alternativo por su id del banco (sin `banco-`). */
export function deporteAlternativoDe(bankId: string): DeporteAlternativo | undefined {
  const id = bankId.replace(/^banco-/, '');
  return DEPORTES_ALTERNATIVOS.find(d => d.id === id);
}

/** El texto de un campo trilingüe en el idioma de la app. */
export const textoDe = (v: T3, lang: Lang): string => v[IDX[lang]];
